examples.template:
VStack(spacing: MonarchTokens.Space.space3) {
    MonarchSegmentedControl(
        "Layout",
        selection: $layout,
        items: [
            MonarchSegmentedItem({{layouts.0.label}}, value: MonarchFileListLayout{{layouts.0.value|case}}),
            MonarchSegmentedItem({{layouts.1.label}}, value: MonarchFileListLayout{{layouts.1.value|case}}),
        ]
    )
    MonarchFileList(
        [
            MonarchFileListItem(id: {{files.0.id}}, name: {{files.0.name}}, size: {{files.0.size}}, meta: {{files.0.meta}}),
            MonarchFileListItem(id: {{files.1.id}}, name: {{files.1.name}}, size: {{files.1.size}}, meta: {{files.1.meta}}),
            MonarchFileListItem(id: {{files.2.id}}, name: {{files.2.name}}, size: {{files.2.size}}, meta: {{files.2.meta}}),
            MonarchFileListItem(id: {{files.3.id}}, name: {{files.3.name}}, size: {{files.3.size}}, meta: {{files.3.meta}}),
            MonarchFileListItem(id: {{files.4.id}}, name: {{files.4.name}}, size: {{files.4.size}}, meta: {{files.4.meta}}),
        ],
        selection: $selection,
        layout: layout,
        label: {{label}},
        bulkActions: [
            MonarchBulkAction(id: "download", title: {{bulkActions.0}}) {},
            MonarchBulkAction(id: "trash", title: {{bulkActions.1}}, isDestructive: true) {},
        ],
        onOpen: { _ in },
        menu: { _ in
            Button({{menu.0}}) {}
            Button({{menu.1}}) {}
            Button({{menu.2}}, role: .destructive) {}
        }
    )
}

examples.code:
VStack(spacing: MonarchTokens.Space.space3) {
    MonarchSegmentedControl(
        "Layout",
        selection: $layout,
        items: [
            MonarchSegmentedItem("List", value: MonarchFileListLayout.list),
            MonarchSegmentedItem("Grid", value: MonarchFileListLayout.grid),
        ]
    )
    MonarchFileList(
        [
            MonarchFileListItem(id: "1", name: "project-brief.pdf", size: 1_800_000, meta: "Edited yesterday"),
            MonarchFileListItem(id: "2", name: "wireframes.png", size: 4_200_000, meta: "Edited 3 days ago"),
            MonarchFileListItem(id: "3", name: "estimates.xlsx", size: 96_000, meta: "Edited last week"),
            MonarchFileListItem(id: "4", name: "kickoff-recording.mp4", size: 182_000_000, meta: "Edited last week"),
            MonarchFileListItem(id: "5", name: "source-assets.zip", size: 54_000_000, meta: "Edited last month"),
        ],
        selection: $selection,
        layout: layout,
        label: "Project files",
        bulkActions: [
            MonarchBulkAction(id: "download", title: "Download") {},
            MonarchBulkAction(id: "trash", title: "Move to trash", isDestructive: true) {},
        ],
        onOpen: { _ in },
        menu: { _ in
            Button("Download") {}
            Button("Rename") {}
            Button("Move to trash", role: .destructive) {}
        }
    )
}
